static const char *root="";static int fixture;
static void js(const char *s){const unsigned char *p=(const unsigned char*)s;putchar('"');for(;*p;p++){if(*p=='"'||*p=='\\')printf("\\%c",*p);else if(*p<32||*p>=127)printf("\\u%04x",*p);else putchar(*p);}putchar('"');}
static int path(char *out,size_t cap,const char *name){return snprintf(out,cap,"%s%s",root,name)>=(int)cap?-1:0;}
/* Only whitelisted regular proc/sys/config observations; never open a device.
 * Symlinks are refused for data reads, including in the fixture backend. */
static int readtext(const char *name,char *b,size_t cap){char p[4096];struct stat st;int fd;ssize_t n;if(path(p,sizeof p,name)||lstat(p,&st)||!S_ISREG(st.st_mode))return -1;fd=open(p,O_RDONLY|O_NOFOLLOW|O_NONBLOCK);if(fd<0)return -1;if(fstat(fd,&st)||!S_ISREG(st.st_mode)){close(fd);return -1;}n=read(fd,b,cap-1);close(fd);if(n<0)return -1;b[n]=0;while(n>0&&(b[n-1]=='\n'||b[n-1]=='\r'||b[n-1]==0))b[--n]=0;return (int)n;}
static void observation(const char *name){char b[8192];printf("{\"source\":");js(name);printf(",\"scope\":");js(fixture?"SYNTHETIC_FIXTURE":"LIVE_FILE_OBSERVATION");if(readtext(name,b,sizeof b)<0){printf(",\"available\":false,\"value\":null,\"uncertainty\":\"absent, unreadable or non-regular; no fallback inference\"}");return;}printf(",\"available\":true,\"value\":");js(b);printf(",\"authenticated_device_identity\":false}");}
static void nodes(void){static const char *names[]={"/dev/flash0","/dev/mtd0","/dev/mtd0ro","/dev/mtdblock0","/dev/watchdog","/dev/watchdog0"};unsigned i;puts("\"device_nodes\":[");for(i=0;i<sizeof names/sizeof names[0];i++){char p[4096];struct stat st;if(i)putchar(',');printf("{\"path\":");js(names[i]);if(path(p,sizeof p,names[i])||lstat(p,&st)){puts(",\"exists\":false}");continue;}printf(",\"exists\":true,\"character\":%s,\"block\":%s,\"symlink\":%s,\"major\":%u,\"minor\":%u,\"read_permission_check\":%s,\"opened\":false,\"backup_read_verified\":false}",S_ISCHR(st.st_mode)?"true":"false",S_ISBLK(st.st_mode)?"true":"false",S_ISLNK(st.st_mode)?"true":"false",major(st.st_rdev),minor(st.st_rdev),access(p,R_OK)==0?"true":"false");}puts("],");}
static void cpu(void){char b[8192],*line,*next;int first=1;printf("\"cpu_platform_fields\":[");if(readtext("/proc/cpuinfo",b,sizeof b)>=0)for(line=b;line&&*line;line=next){next=strchr(line,'\n');if(next)*next++=0;if(!strncmp(line,"system type",11)||!strncmp(line,"cpu model",9)||!strncmp(line,"Hardware",8)){if(!first)putchar(',');first=0;js(line);}}puts("],");}
static int numeric(const char *s){if(!*s)return 0;for(;*s;s++)if(!isdigit((unsigned char)*s))return 0;return 1;}
static int relevant(const char *s){return strstr(s,"watch")||strstr(s,"wdt")||strstr(s,"httpd")||strstr(s,"config")||strstr(s,"lte")||strstr(s,"modem")||strstr(s,"cwmp")||strstr(s,"ppp")||strstr(s,"tddp");}
static void conditions(void){char p[4096],name[4096],b[256];DIR *dir;struct dirent *e;int first=1;printf("\"relevant_process_names\":[");if(!path(p,sizeof p,"/proc")&&(dir=opendir(p))){while((e=readdir(dir)))if(numeric(e->d_name)){if(snprintf(name,sizeof name,"/proc/%s/comm",e->d_name)>=(int)sizeof name)continue;if(readtext(name,b,sizeof b)>=0&&relevant(b)){if(!first)putchar(',');first=0;printf("{\"pid\":");js(e->d_name);printf(",\"comm\":");js(b);putchar('}');}}closedir(dir);}puts("],");first=1;printf("\"init_script_names\":[");if(!path(p,sizeof p,"/etc/init.d")&&(dir=opendir(p))){while((e=readdir(dir)))if(e->d_name[0]!='.'){if(!first)putchar(',');first=0;js(e->d_name);}closedir(dir);}puts("],");}
static void geometry(void){char p[4096],name[4096];DIR *dir;struct dirent *e;int first=1;printf("\"mtd_sysfs\":[");if(!path(p,sizeof p,"/sys/class/mtd")&&(dir=opendir(p))){while((e=readdir(dir)))if(!strncmp(e->d_name,"mtd",3)&&numeric(e->d_name+3)){static const char *attrs[]={"name","size","erasesize","type","flags"};unsigned i;if(!first)putchar(',');first=0;printf("{\"device\":");js(e->d_name);printf(",\"attributes\":[");for(i=0;i<sizeof attrs/sizeof attrs[0];i++){if(i)putchar(',');if(snprintf(name,sizeof name,"/sys/class/mtd/%s/%s",e->d_name,attrs[i])>=(int)sizeof name)continue;observation(name);}printf("]}");}closedir(dir);}puts("],");}
